def discover_runs(runs_dir: Path = DEFAULT_RUNS_DIR) -> pd.DataFrame:
    """Read ``runs_dir/index.csv`` and return a DataFrame ordered by run_id.

    Always returns a DataFrame; if the index is missing or empty, returns an
