# ── keyboard shortcuts ────────────────────────────────────────────────────

def keyPressEvent(self, event: QKeyEvent):
    key = event.key()
    if key == Qt.Key_J:
        self._prev_roi()
    elif key == Qt.Key_K:
        self._next_roi()
    elif key == Qt.Key_S:
        self._save()
    elif key == Qt.Key_Space:
        self._save_and_next()
    elif key == Qt.Key_1:
        self.trace_panel.toggle_trace("short")
    elif key == Qt.Key_2:
        self.trace_panel.toggle_trace("long")
    elif key == Qt.Key_3:
        self.trace_panel.toggle_trace("F0trend")
    elif key == Qt.Key_4:
        self.trace_panel.toggle_trace("F0")
    elif key == Qt.Key_M:
        self.image_panel.mask_chk.toggle()
    elif key == Qt.Key_Z:

        self.curation.clear()

