            self._f_curves[name].setPen(_make_pen(_pg_color(hex_c), width=lw + 1))
        if name in self._dff_curves:
            r, g, b = _pg_color(hex_c)
            self._dff_curves[name].setPen(
                _make_pen((r, g, b, self._dff_alpha), width=lw))

    def _apply_all_pens(self) -> None:
        lw = self._current_lw
        if "F" in self._f_curves:
            self._f_curves["F"].setPen(_make_pen("#222", width=max(1, lw - 1)))
        for name in TRACE_KEYS:
            self._apply_curve_pen(name)

    # ── zoom → line width ─────────────────────────────────────────────────────

    def _on_range_changed(self, vb, ranges) -> None:
        if self._full_x_span is None or self._full_x_span <= 0:
            return
        x_span = ranges[0][1] - ranges[0][0]
        if x_span <= 0:
            return
        zoom = self._full_x_span / x_span
        new_lw = max(1, min(6, int(1 + zoom ** 0.5)))
        if new_lw == self._current_lw:
            return
        self._current_lw = new_lw
        self._apply_all_pens()

    # ── hover legend ──────────────────────────────────────────────────────────

    def eventFilter(self, obj, event):
        if obj is self.f_plot.viewport():
            if event.type() == QEvent.Enter:
                if self._hover_legend is not None:
                    self._hover_legend.setVisible(True)
            elif event.type() == QEvent.Leave:
                if self._hover_legend is not None:
                    self._hover_legend.setVisible(False)
        return super().eventFilter(obj, event)

    def _rebuild_hover_legend(self) -> None:
        lg = self._hover_legend
        if lg is None:
            return
        was_visible = lg.isVisible()
        lg.clear()
        for name, curve in self._f_curves.items():
            if name == "F":
                continue
            btn = self._legend_btns.get(name)
            if btn is not None and btn.isVisible() and btn.isChecked():
                lg.addItem(curve, name)
        lg.setVisible(was_visible)

    # ── plot color submenu ────────────────────────────────────────────────────

    def _build_plot_color_menu(self) -> None:
        for pw in (self.f_plot, self.dff_plot):
            try:
                vb_menu = pw.getViewBox().menu
                if vb_menu is None:
                    continue
                vb_menu.addSeparator()
                color_sub = vb_menu.addMenu("Set trace color…")
                for name in TRACE_KEYS:
                    act = color_sub.addAction(name)
                    act.triggered.connect(lambda _, n=name: self._pick_color(n))
            except Exception:
                pass

    # ── curve initialisation ──────────────────────────────────────────────────

    def init_curves(self):
        self.f_plot.clear()
        self.dff_plot.clear()
        self._f_curves = {}
        self._dff_curves = {}

        self._f_curves["F"] = self.f_plot.plot(pen=_make_pen("#222", width=1))

        for name in TRACE_KEYS:
            self._f_curves[name] = self.f_plot.plot(
                pen=_make_pen(_pg_color(self._colors.get(name, "#888")),
                              width=self._current_lw + 1))

        zero = pg.InfiniteLine(pos=0, angle=0,
                               pen=pg.mkPen(color=(180, 180, 180), width=1,
                                            style=Qt.DashLine))
        self.dff_plot.addItem(zero)

        for name in TRACE_KEYS:
            r, g, b = _pg_color(self._colors.get(name, "#888"))
            self._dff_curves[name] = self.dff_plot.plot(
                pen=_make_pen((r, g, b, self._dff_alpha), width=self._current_lw))

        # Hover legend (rebuilt each time to pick up new curve objects)
        if self._hover_legend is not None:
            try:
                self.f_plot.getPlotItem().removeItem(self._hover_legend)
            except Exception:
                pass
        self._hover_legend = pg.LegendItem(offset=(10, 10))
        self._hover_legend.setParentItem(self.f_plot.getPlotItem())
        self._hover_legend.setVisible(False)
        self._rebuild_hover_legend()

        # Dynamic line width — reconnect each time (clear + reconnect avoids double-connect)
        try:
            self.f_plot.getViewBox().sigRangeChanged.disconnect(self._on_range_changed)
        except Exception:
            pass
        self.f_plot.getViewBox().sigRangeChanged.connect(self._on_range_changed)

        # Color submenu in plot context menu (only added once)
        if not self._color_menu_built:
            self._build_plot_color_menu()
            self._color_menu_built = True

    def toggle_trace(self, name: str):
        btn = self._legend_btns.get(name)
        if btn:
            btn.setChecked(not btn.isChecked())

    def _on_toggle(self, name: str, checked: bool):
        for curves in (self._f_curves, self._dff_curves):
            if name in curves:
                curves[name].setVisible(checked)
        self._rebuild_hover_legend()

    def _on_alpha_changed(self, value: int):
        self._dff_alpha = int(value / 100 * 255)
        for name, curve in self._dff_curves.items():
            r, g, b = _pg_color(self._colors.get(name, "#888"))
            curve.setPen(_make_pen((r, g, b, self._dff_alpha), width=self._current_lw))

    def _home(self):
        self.f_plot.enableAutoRange()
        self.dff_plot.enableAutoRange()

    def set_available_keys(self, keys: list[str]):
        empty = np.array([])
        for name, btn in self._legend_btns.items():
            available = name in keys
            btn.setVisible(available)
            if not available:
                if name in self._f_curves:
                    self._f_curves[name].setData(empty, empty)
                if name in self._dff_curves:
                    self._dff_curves[name].setData(empty, empty)
        self._rebuild_hover_legend()

    def set_slot_label(self, slot_key: str, label: str | None):
        btn = self._legend_btns.get(slot_key)
        if btn is None:
            return
        i = list(self._legend_btns).index(slot_key) + 1
        btn.setText(f"{i}:{slot_key}" if label is None else f"{i}:{label}")

    def update(self, timestamps, F, baselines, dffs):
        if len(timestamps) > 1:
            span = float(timestamps[-1] - timestamps[0])
            if span > 0:
                self._full_x_span = span
        self._f_curves["F"].setData(timestamps, F)
        for name, trace in baselines.items():
            if name in self._f_curves:
                self._f_curves[name].setData(timestamps, trace)
        for name, trace in dffs.items():
            if name in self._dff_curves:
                self._dff_curves[name].setData(timestamps, trace)

