        # Accept right-click so mouseClickEvent receives it.
        if not ev.isExit():
            ev.acceptClicks(Qt.RightButton)

    def mouseClickEvent(self, ev):
        if ev.button() == Qt.RightButton:
            ev.accept()
            if self._on_right_click is not None:
                self._on_right_click(self._trace_name)
        else:
            super().mouseClickEvent(ev)

